// More of Loopy's own diagrams: analog circuits, DSP, control systems and probability. Extends brain-diagrams.js.
import { Cv, mk, D } from "./brain-diagrams.js?v=446";
const done = (c) => c.root;
const P = Cv.prototype;
// Local-coordinate parts: each starts at (x, y) and ends L further along the (rotated) axis. Returns the absolute end pin.
P.part = function (kind, x, y, rot, cls, label, lpos) {
  const L = { res: 40, cap: 24, ind: 48, diode: 30, zener: 30, led: 30, bat: 24, ac: 36, sw: 36 }[kind], g = this.add(mk("g", { transform: "translate(" + x + " " + y + ") rotate(" + (rot || 0) + ")" })), k = cls || "mid", ln = (d) => g.append(mk("path", { d, class: "dg-w " + k, fill: "none" }));
  if (kind === "res") ln("M0 0H8L11 -7L17 7L23 -7L29 7L32 0H40");
  else if (kind === "cap") { ln("M0 0H9M15 0H24"); g.append(mk("path", { d: "M9 -11V11M15 -11V11", class: "dg-w " + k, fill: "none" })); }
  else if (kind === "ind") ln("M0 0H6a6 6 0 0 1 12 0a6 6 0 0 1 12 0a6 6 0 0 1 12 0H48");
  else if (kind === "diode" || kind === "zener" || kind === "led") { ln("M0 0H8M22 0H30"); g.append(mk("path", { d: "M8 -9V9L22 0Z", class: "dg-gate g-and" })); ln(kind === "zener" ? "M19 -12L22 -9V9L25 12" : "M22 -9V9"); if (kind === "led") ln("M12 -13l6 -6M17 -9l6 -6"); }
  else if (kind === "bat") { ln("M0 0H9M15 0H24"); g.append(mk("path", { d: "M9 -12V12M15 -6V6", class: "dg-w " + k, fill: "none" })); }
  else if (kind === "ac") { ln("M0 0H4M32 0H36"); g.append(mk("circle", { cx: 18, cy: 0, r: 14, class: "dg-box ff" })); ln("M9 0q4.5 -9 9 0t9 0"); }
  else if (kind === "sw") { ln("M0 0H8M28 0H36M8 0L26 -10"); }
  if (label) { const t = mk("text", { x: L / 2, y: lpos === "below" ? 24 : -14, "text-anchor": "middle", class: "dg-t s", transform: "rotate(" + (-(rot || 0)) + " " + (L / 2) + " " + (lpos === "below" ? 20 : -10) + ")" }, label); g.append(t); }
  const a = (rot || 0) * Math.PI / 180; return [Math.round(x + L * Math.cos(a)), Math.round(y + L * Math.sin(a))];
};
P.gnd = function (x, y, cls) { this.add(mk("path", { d: "M" + x + " " + y + "v8M" + (x - 10) + " " + (y + 8) + "h20M" + (x - 6) + " " + (y + 12) + "h12M" + (x - 2) + " " + (y + 16) + "h4", class: "dg-w " + (cls || "in"), fill: "none" })); };
P.bjt = function (x, y, kind) { // base pin at (x,y); returns {b, c, e}
  const g = this.add(mk("g", { transform: "translate(" + x + " " + y + ")" })); g.append(mk("circle", { cx: 20, cy: 0, r: 22, class: "dg-box ff", "fill-opacity": ".35" })); g.append(mk("path", { d: "M0 0H14M14 -14V14M14 -6L28 -20V-30M14 6L28 20V30", class: "dg-w mid", fill: "none" }));
  g.append(mk("path", kind === "pnp" ? { d: "M16 -8l7 -1l-3 7z", class: "dg-ar mid", transform: "rotate(0)" } : { d: "M28 20l-9 -1l4 -7z", class: "dg-ar mid" })); return { b: [x, y], c: [x + 28, y - 30], e: [x + 28, y + 30] };
};
P.opamp = function (x, y, w) { w = w || 64; const g = this.add(mk("g", { transform: "translate(" + x + " " + y + ")" })); g.append(mk("path", { d: "M0 -34V34L" + w + " 0Z", class: "dg-gate g-and" })); g.append(mk("text", { x: 7, y: -12, class: "dg-t" }, "−")); g.append(mk("text", { x: 7, y: 22, class: "dg-t" }, "+")); return { n: [x, y - 18], p: [x, y + 18], o: [x + w, y] }; };
P.axes = function (x, y, w, h, xl, yl, o) { o = o || {}; this.wire([[x, y + h], [x + w, y + h]], "ax", true); this.wire([[x, y + h], [x, y - 4]], "ax", true); if (xl) this.txt(x + w, y + h + 14, xl, { a: "end", c: "s" }); if (yl) this.txt(x - 4, y - 8, yl, { a: o.ya || "start", c: "s" }); };
P.curve = function (pts, cls, w) { this.add(mk("polyline", { points: pts.map(p => p[0].toFixed(1) + "," + p[1].toFixed(1)).join(" "), class: "dg-w " + (cls || "out"), fill: "none", "stroke-width": w || 2.6 })); };
P.fillp = function (pts, cls) { this.add(mk("polygon", { points: pts.map(p => p[0].toFixed(1) + "," + p[1].toFixed(1)).join(" "), class: "dg-fill " + cls })); };
P.sample = function (n, f, a, b) { const o = []; for (let i = 0; i <= n; i++) { const t = a + (b - a) * i / n; o.push(f(t)); } return o; };
// ---- Analog circuits ----
D.diodeIV = { title: "Diode I\u2013V characteristic", cap: "Almost no current in reverse. In forward bias the current rises steeply after the knee voltage (about 0.7 V for silicon). At large reverse voltage the diode breaks down.", draw() {
  const c = new Cv(360, 250, "Diode characteristic"); c.wire([[24, 150], [340, 150]], "ax", true); c.wire([[120, 236], [120, 14]], "ax", true); c.txt(338, 168, "V", { a: "end", c: "s" }); c.txt(128, 20, "I", { c: "s" });
  c.curve(c.sample(24, (t) => [120 + 24 + t * 30, 150 - 4 * (Math.exp(t * 2.1) - 1)], 0, 6).filter(p => p[1] > 24).concat([[120 + 24 + 6 * 30 * 0 + 3.8 * 30, 22]]).slice(0, -1), "out"); c.curve([[120, 150], [144, 150]], "out");
  c.curve([[40, 152], [120, 152]], "mid"); c.curve([[40, 152], [36, 156], [34, 196], [32, 232]], "clk", 3);
  c.add(mk("line", { x1: 144, y1: 144, x2: 144, y2: 156, class: "dg-w ax" })); c.txt(150, 186, "knee \u2248 0.7 V (Si)", { c: "s" }); c.txt(220, 80, "Forward bias:", { c: "g" }); c.txt(220, 94, "current rises fast", { c: "s" }); c.txt(40, 136, "Reverse bias:", { c: "b" }); c.txt(36, 168, "tiny leakage", { c: "s" }); c.txt(44, 222, "Breakdown", { c: "m" }); return done(c); } };
D.halfwave = { title: "Half-wave rectifier", cap: "The diode conducts only in the positive half cycle, so the load gets pulses of one polarity. Vdc = Vm/π, ripple factor = 1.21, efficiency = 40.6%.", draw() {
  const c = new Cv(380, 250, "Half wave rectifier"); let e = c.part("ac", 20, 40, 0); c.wire([[20, 40], [20, 40]], "in"); c.wire([e, [e[0] + 12, 40]], "in"); e = c.part("diode", e[0] + 12, 40, 0, "out", "D"); c.wire([e, [270, 40], [270, 54]], "in"); c.part("res", 270, 54, 90, "mid", "RL"); c.wire([[270, 94], [270, 124], [20, 124], [20, 40]], "in"); c.dot(270, 124); c.txt(60, 16, "AC input", { c: "b" }); c.txt(282, 84, "Vout", { c: "g" });
  const x0 = 60, y0 = 170; c.txt(4, y0 + 4, "in", { c: "b" }); c.curve(c.sample(40, (t) => [x0 + t * 9, y0 - 26 * Math.sin(t * 0.5 * 2)], 0, 29), "in"); c.txt(4, y0 + 52, "out", { c: "g" }); c.curve(c.sample(80, (t) => [x0 + t * 9, y0 + 56 - Math.max(0, 26 * Math.sin(t * 0.5 * 2))], 0, 29), "out"); return done(c); } };
D.bridge = { title: "Bridge rectifier", cap: "Four diodes steer both half cycles through the load in the same direction, so the output is full-wave. Vdc = 2Vm/\u03C0, ripple factor = 0.48, efficiency = 81.2%.", draw() {
  const c = new Cv(380, 230, "Bridge rectifier"), L = [120, 110], T = [180, 50], R = [240, 110], B = [180, 170];
  const onEdge = (p, q, cls) => { const dx = q[0] - p[0], dy = q[1] - p[1], len = Math.hypot(dx, dy), ux = dx / len, uy = dy / len, ang = Math.atan2(dy, dx) * 180 / Math.PI, st = [p[0] + dx / 2 - 15 * ux, p[1] + dy / 2 - 15 * uy]; c.wire([p, st], "mid"); c.wire([[st[0] + 30 * ux, st[1] + 30 * uy], q], "mid"); c.part("diode", st[0], st[1], ang, cls); };
  onEdge(L, T, "out"); onEdge(R, T, "out"); onEdge(B, L, "out"); onEdge(B, R, "out");
  c.wire([L, [60, 110]], "in"); c.txt(8, 106, "AC ~", { c: "b" }); c.wire([R, [300, 110]], "in"); c.txt(304, 106, "~ AC", { c: "b" });
  c.wire([T, [180, 20], [340, 20], [340, 60]], "out"); c.part("res", 340, 60, 90, "mid", "RL"); c.wire([[340, 100], [340, 200], [180, 200], B], "out"); c.txt(190, 46, "+", { c: "g" }); c.txt(190, 192, "\u2212", { c: "m" }); c.txt(300, 220, "DC output across RL", { c: "s", a: "middle" }); return done(c); } };
D.zenerreg = { title: "Zener voltage regulator", cap: "The Zener diode holds the load voltage almost constant. Rs = (Vin − Vz) / (Iz + IL).", draw() {
  const c = new Cv(340, 200, "Zener regulator"); c.part("bat", 20, 40, 0, "in", "Vin"); c.wire([[44, 40], [70, 40]], "in"); let e = c.part("res", 70, 40, 0, "mid", "Rs"); c.wire([e, [230, 40]], "in"); c.dot(180, 40, "in"); c.wire([[180, 40], [180, 60]], "in"); c.part("zener", 180, 90, -90, "clk"); c.txt(172, 80, "Zener", { a: "end", c: "m" }); c.wire([[180, 90], [180, 150]], "in"); c.wire([[230, 40], [230, 60]], "in"); c.part("res", 230, 60, 90, "mid", "RL"); c.wire([[230, 100], [230, 150], [20, 150], [20, 40]], "in"); c.dot(180, 150, "in"); c.txt(244, 86, "Vout = Vz", { c: "g" }); return done(c); } };
D.bjtbias = { title: "Voltage-divider bias of a BJT", cap: "R1 and R2 fix the base voltage, RE stabilises the Q point. The Q point must sit in the middle of the load line.", draw() {
  const c = new Cv(340, 270, "BJT voltage divider bias"); c.wire([[60, 20], [250, 20]], "fb"); c.txt(256, 24, "+VCC", { c: "m" }); const t = c.bjt(140, 130, "npn");
  c.wire([[80, 20], [80, 50]], "in"); c.part("res", 80, 50, 90, "mid", "R1"); c.wire([[80, 90], [80, 130], t.b], "in"); c.dot(80, 130, "in"); c.wire([[80, 130], [80, 150]], "in"); c.part("res", 80, 150, 90, "mid", "R2"); c.wire([[80, 190], [80, 232], [250, 232]], "in");
  c.wire([[168, 20], [168, 40]], "in"); c.part("res", 168, 40, 90, "mid", "RC"); c.wire([[168, 80], t.c], "in"); c.wire([t.c, [200, t.c[1]]], "out", true); c.txt(206, t.c[1] + 4, "Vout", { c: "g" }); c.wire([t.e, [168, 168]], "in"); c.part("res", 168, 168, 90, "mid", "RE"); c.wire([[168, 208], [168, 232]], "in"); c.gnd(168, 232); return done(c); } };
D.bjtchar = { title: "BJT output characteristics and load line", cap: "IC against VCE for different base currents IB. The DC load line crosses the curves; the Q point (operating point) is placed in the active region.", draw() {
  const c = new Cv(360, 240, "BJT output characteristics"); c.axes(50, 20, 290, 180, "VCE", "IC"); c.fillp([[50, 200], [90, 200], [90, 20], [50, 20]], "sat"); c.fillp([[50, 200], [340, 200], [340, 188], [50, 188]], "cut");
  [150, 120, 92, 66].forEach((y, i) => { c.curve([[50, 200], [64, y + 14], [90, y], [340, y - 6 - i * 0]], "out", 2.2); c.txt(344, y - 3, "IB" + (4 - i), { c: "s" }); });
  c.add(mk("line", { x1: 50, y1: 36, x2: 300, y2: 200, class: "dg-w clk" })); c.dot(166, 112, "clk"); c.txt(172, 108, "Q", { c: "m" }); c.txt(56, 44, "Saturation", { c: "s" }); c.txt(170, 216, "Active region", { a: "middle", c: "g" }); c.txt(270, 196, "Cutoff", { a: "middle", c: "s" }); c.txt(10, 34, "load line", { c: "m" }); return done(c); } };
D.ceamp = { title: "Common-emitter amplifier", cap: "The input signal goes through a coupling capacitor, the transistor amplifies it, and the output is 180° out of phase. CE bypasses RE for AC.", draw() {
  const c = new Cv(360, 280, "Common emitter amplifier"); c.wire([[70, 20], [260, 20]], "fb"); c.txt(266, 24, "+VCC", { c: "m" }); const t = c.bjt(130, 130, "npn");
  c.wire([[80, 20], [80, 50]], "in"); c.part("res", 80, 50, 90, "mid", "R1"); c.wire([[80, 90], [80, 130]], "in"); c.dot(80, 130, "in"); c.part("res", 80, 150, 90, "mid", "R2"); c.wire([[80, 130], [80, 150]], "in"); c.wire([[80, 190], [80, 240], [260, 240]], "in");
  c.wire([[80, 130], [96, 130]], "in"); c.part("cap", 40, 130, 0, "clk", "C1"); c.wire([[64, 130], [80, 130]], "in"); c.txt(4, 134, "Vin", { c: "b" }); c.wire([[96, 130], t.b], "in");
  c.wire([[158, 20], [158, 40]], "in"); c.part("res", 158, 40, 90, "mid", "RC"); c.wire([[158, 80], t.c], "in"); c.wire([t.c, [200, t.c[1]]], "in"); c.part("cap", 200, t.c[1], 0, "clk", "C2"); c.wire([[224, t.c[1]], [270, t.c[1]]], "out", true); c.txt(274, t.c[1] + 4, "Vout", { c: "g" });
  c.wire([t.e, [158, 170]], "in"); c.dot(158, 180, "in"); c.part("res", 158, 170, 90, "mid", "RE"); c.wire([[158, 210], [158, 240]], "in"); c.wire([[158, 190], [210, 190]], "in"); c.part("cap", 210, 190, 90, "clk", "CE"); c.wire([[210, 214], [210, 240]], "in"); c.gnd(158, 240); return done(c); } };
D.mosfet = { title: "MOSFET drain characteristics", cap: "Below the knee (VDS < VGS − Vt) the MOSFET acts like a resistor (triode). Beyond it, the current is almost constant (saturation) and the device works as an amplifier.", draw() {
  const c = new Cv(390, 230, "MOSFET characteristics"); c.axes(50, 20, 290, 180, "VDS", "ID"); c.fillp([[50, 200], [50, 20], [130, 20], [130, 200]], "sat");
  [[130, 150], [150, 100], [170, 60]].forEach(([vx, y], i) => { c.curve([[50, 200], [70, 200 - (200 - y) * 0.7], [vx, y], [340, y - 8]], "out", 2.4); c.txt(344, y - 4, "VGS" + (i + 1), { c: "s" }); });
  c.curve([[50, 200], [90, 130], [130, 70], [170, 26]], "clk", 1.8); c.txt(60, 28, "Triode", { c: "s" }); c.txt(236, 216, "Saturation (amplifier)", { a: "middle", c: "g" }); c.txt(192, 28, "VDS = VGS − Vt", { c: "m" }); return done(c); } };
D.fbloop = { title: "Negative feedback amplifier", cap: "The feedback network β returns a part of the output to the input where it is subtracted. Gain with feedback Af = A / (1 + Aβ).", draw() {
  const c = new Cv(380, 190, "Feedback amplifier block diagram"); c.txt(4, 64, "Xi", { c: "b" }); c.wire([[26, 60], [76, 60]], "in", true); c.add(mk("circle", { cx: 90, cy: 60, r: 14, class: "dg-box ff" })); c.txt(90, 65, "Σ", { a: "middle", c: "b" }); c.txt(70, 48, "+", { c: "b" }); c.txt(96, 90, "−", { c: "m" });
  c.wire([[104, 60], [140, 60]], "mid", true); c.box(140, 36, 80, 48, "Amplifier|A", "ff"); c.wire([[220, 60], [300, 60]], "out", true); c.txt(304, 64, "Xo", { c: "g" }); c.dot(260, 60, "out"); c.wire([[260, 60], [260, 144], [200, 144]], "fb"); c.box(120, 124, 80, 40, "Feedback|β", "ff"); c.wire([[120, 144], [90, 144], [90, 74]], "fb", true); return done(c); } };
D.closedloop = { title: "Closed-loop control system", cap: "The controller works on the error e = r − b. The sensor feeds the output back, so the system corrects itself. C/R = G / (1 + GH).", draw() {
  const c = new Cv(400, 200, "Closed loop control system"); c.txt(4, 64, "R(s)", { c: "b" }); c.wire([[34, 60], [76, 60]], "in", true); c.add(mk("circle", { cx: 90, cy: 60, r: 14, class: "dg-box ff" })); c.txt(70, 48, "+", { c: "b" }); c.txt(96, 90, "−", { c: "m" }); c.wire([[104, 60], [140, 60]], "mid", true); c.txt(112, 52, "E(s)", { c: "s" });
  c.box(140, 36, 90, 48, "Controller|+ Plant G(s)", "ff"); c.wire([[230, 60], [320, 60]], "out", true); c.txt(324, 64, "C(s)", { c: "g" }); c.dot(280, 60, "out"); c.wire([[280, 60], [280, 150], [210, 150]], "fb"); c.box(120, 130, 90, 40, "Sensor H(s)", "ff"); c.wire([[120, 150], [90, 150], [90, 74]], "fb", true); return done(c); } };
D.openloop = { title: "Open-loop control system", cap: "No feedback. The controller does not know the real output, so errors from disturbances are not corrected (for example, a toaster with a fixed timer).", draw() {
  const c = new Cv(430, 110, "Open loop control system"); c.txt(4, 58, "Input", { c: "b" }); c.wire([[40, 54], [80, 54]], "in", true); c.box(80, 30, 100, 48, "Controller", "ff"); c.wire([[180, 54], [210, 54]], "mid", true); c.box(210, 30, 90, 48, "Plant", "ff"); c.wire([[300, 54], [350, 54]], "out", true); c.txt(354, 58, "Output", { c: "g" }); c.txt(200, 100, "No feedback path", { a: "middle", c: "s" }); return done(c); } };

// ---- Op-amp circuits ----
D.opinv = { title: "Inverting amplifier", cap: "Gain = −Rf / Rin. The + input is at ground, so the − input is a virtual ground and the output is inverted.", draw() {
  const c = new Cv(380, 210, "Inverting amplifier"), o = c.opamp(170, 100); c.txt(4, 84, "Vin", { c: "b" }); c.wire([[34, 82], [60, 82]], "in"); let e = c.part("res", 60, 82, 0, "mid", "Rin"); c.wire([e, o.n[0] === 170 ? [140, 82] : e, [140, 82], [140, o.n[1]], o.n], "in"); c.dot(140, 82, "in");
  c.wire([[140, 82], [140, 30], [170, 30]], "fb"); const e2 = c.part("res", 170, 30, 0, "clk", "Rf"); c.wire([e2, [290, 30], [290, 100]], "fb"); c.wire([o.p, [150, o.p[1]], [150, 160]], "in"); c.gnd(150, 160); c.wire([o.o, [330, 100]], "out", true); c.dot(290, 100, "out"); c.txt(334, 104, "Vout", { c: "g" }); return done(c); } };
D.opnon = { title: "Non-inverting amplifier", cap: "Gain = 1 + Rf / Rin. The output is in phase with the input and the gain is never less than 1.", draw() {
  const c = new Cv(380, 230, "Non-inverting amplifier"), o = c.opamp(150, 100); c.txt(4, 122, "Vin", { c: "b" }); c.wire([[34, 118], o.p], "in");
  c.wire([o.n, [120, o.n[1]], [120, 160]], "mid"); c.dot(120, 160, "mid"); c.part("res", 120, 160, 90, "mid", "Rin"); c.gnd(120, 200);
  c.wire([[120, 160], [140, 160]], "fb"); const e = c.part("res", 140, 160, 0, "clk", "Rf"); c.wire([e, [260, 160], [260, 100]], "fb"); c.wire([o.o, [330, 100]], "out", true); c.dot(260, 100, "out"); c.txt(334, 104, "Vout", { c: "g" }); return done(c); } };
D.opint = { title: "Op-amp integrator", cap: "Vout = −(1/RC) ∫ Vin dt. A square wave in gives a triangle wave out.", draw() {
  const c = new Cv(380, 210, "Integrator"), o = c.opamp(170, 100); c.txt(4, 84, "Vin", { c: "b" }); c.wire([[34, 82], [60, 82]], "in"); let e = c.part("res", 60, 82, 0, "mid", "R"); c.wire([e, [140, 82], [140, o.n[1]], o.n], "in"); c.dot(140, 82, "in"); c.wire([[140, 82], [140, 30], [170, 30]], "fb"); const e2 = c.part("cap", 170, 30, 0, "clk", "C"); c.wire([e2, [290, 30], [290, 100]], "fb"); c.wire([o.p, [150, o.p[1]], [150, 160]], "in"); c.gnd(150, 160); c.wire([o.o, [330, 100]], "out", true); c.dot(290, 100, "out"); c.txt(334, 104, "Vout", { c: "g" }); return done(c); } };
D.opsum = { title: "Summing amplifier", cap: "Vout = −Rf (V1/R1 + V2/R2). Each input is amplified and added. It is the heart of a simple audio mixer.", draw() {
  const c = new Cv(380, 230, "Summing amplifier"), o = c.opamp(190, 120); c.txt(4, 64, "V1", { c: "b" }); c.txt(4, 124, "V2", { c: "b" }); c.wire([[26, 60], [44, 60]], "in"); c.part("res", 44, 60, 0, "mid", "R1"); c.wire([[84, 60], [150, 60], [150, o.n[1]], o.n], "in"); c.wire([[26, 120], [44, 120]], "in"); c.part("res", 44, 120, 0, "mid", "R2"); c.wire([[84, 120], [150, 120], [150, 60]], "in"); c.dot(150, 60, "in");
  c.wire([[150, 60], [150, 22], [190, 22]], "fb"); const e2 = c.part("res", 190, 22, 0, "clk", "Rf"); c.wire([e2, [300, 22], [300, 120]], "fb"); c.wire([o.p, [170, o.p[1]], [170, 190]], "in"); c.gnd(170, 190); c.wire([o.o, [340, 120]], "out", true); c.dot(300, 120, "out"); c.txt(344, 124, "Vout", { c: "g" }); return done(c); } };
D.t555 = { title: "555 timer in astable mode", cap: "C charges through RA + RB and discharges through RB, so the output is a square wave. f = 1.44 / ((RA + 2RB) C). Monostable pulse width T = 1.1 R C.", draw() {
  const c = new Cv(400, 250, "555 timer astable"); c.box(150, 50, 130, 120, "555|TIMER", "ff"); const pin = (x, y, t, side) => c.txt(side === "l" ? x + 4 : x - 4, y + 4, t, { a: side === "l" ? "start" : "end", c: "s" });
  pin(150, 70, "TRIG", "l"); pin(150, 100, "THR", "l"); pin(150, 130, "DIS", "l"); pin(280, 80, "OUT", "r"); pin(280, 120, "VCC", "r");
  c.wire([[110, 20], [300, 20]], "fb"); c.txt(304, 24, "+VCC", { c: "m" }); c.wire([[130, 20], [130, 40]], "in"); c.part("res", 130, 40, 90, "mid", "RA"); c.wire([[130, 80], [130, 130], [150, 130]], "in"); c.dot(130, 130, "in"); c.part("res", 130, 130, 90, "mid", "RB"); c.wire([[130, 170], [130, 196]], "in"); c.dot(130, 190, "in"); c.wire([[130, 190], [110, 190], [110, 70], [150, 70]], "in"); c.dot(110, 100, "in"); c.wire([[110, 100], [150, 100]], "in"); c.part("cap", 130, 196, 90, "clk", "C"); c.wire([[130, 220], [130, 232]], "in"); c.gnd(130, 232);
  c.wire([[280, 80], [370, 80]], "out", true); c.txt(374, 84, "Out", { c: "g" }); c.wire([[280, 120], [290, 120], [290, 20]], "fb"); return done(c); } };
D.classes = { title: "Power amplifier classes", cap: "Class A conducts for 360°, B for 180°, AB for a little more than 180° and C for less than 180°. Efficiency rises from A (25–50%) to B (78.5%) to C (above 90%), but distortion also rises.", draw() {
  const c = new Cv(380, 290, "Power amplifier classes"); const row = (y, name, cut, col) => { c.txt(4, y + 4, name, { c: col }); c.add(mk("line", { x1: 60, y1: y, x2: 360, y2: y, class: "dg-w ax", "stroke-dasharray": "3 4" })); c.curve(c.sample(60, (t) => [60 + t * 5, y - 24 * Math.sin(t * 0.21 * 1)], 0, 60).map((p, i, a) => p), "in", 1.2); const pts = c.sample(120, (t) => [60 + t * 2.5, y - Math.max(cut, 24 * Math.sin(t * 0.21 * 0.5 * 2 * 0 + (t / 60) * 2 * Math.PI * 2)) * 0], 0, 120); };
  const draw = (y, name, thr, col) => { c.txt(4, y + 4, name, { c: col }); c.add(mk("line", { x1: 60, y1: y, x2: 360, y2: y, class: "dg-w ax", "stroke-dasharray": "3 4" })); const w = 2 * Math.PI * 2 / 300; c.curve(c.sample(150, (t) => [60 + t * 2, y - 24 * Math.sin(t * 2 * w)], 0, 150), "in", 1.2); const pts = c.sample(150, (t) => { const v = 24 * Math.sin(t * 2 * w); return [60 + t * 2, y - Math.max(v, thr)]; }, 0, 150); c.curve(pts.map((p, i) => p), col === "g" ? "out" : "out", 2.6); };
  draw(40, "A", -99, "g"); c.txt(300, 28, "360°", { c: "s" }); draw(110, "B", 0, "g"); c.txt(300, 98, "180°", { c: "s" }); draw(180, "AB", -8, "g"); c.txt(300, 168, "> 180°", { c: "s" }); draw(250, "C", 12, "g"); c.txt(300, 238, "< 180°", { c: "s" }); return done(c); } };
// ---- DSP ----
D.sampling = { title: "Sampling a signal", cap: "Sampling takes values of x(t) at equal time steps Ts. To rebuild the signal without aliasing, the sampling frequency must satisfy fs ≥ 2 fmax (Nyquist rate).", draw() {
  const c = new Cv(380, 220, "Sampling"); c.axes(30, 20, 330, 160, "t", "x"); const f = (t) => 100 - 60 * Math.sin(t * 0.16); c.curve(c.sample(150, (t) => [30 + t * 2, f(t)], 0, 150), "in", 2); for (let i = 0; i <= 18; i++) { const x = 30 + i * 17, y = f(i * 8.5); c.add(mk("line", { x1: x, y1: 100, x2: x, y2: y, class: "dg-w out", "stroke-width": 2 })); c.dot(x, y, "out"); }
  c.add(mk("line", { x1: 30, y1: 100, x2: 360, y2: 100, class: "dg-w ax", "stroke-dasharray": "2 4" })); c.txt(30, 204, "Ts", { c: "m" }); c.wire([[30, 190], [47, 190]], "clk"); c.wire([[47, 190], [30, 190]], "clk"); c.txt(190, 214, "samples x[n] = x(nTs)", { a: "middle", c: "g" }); return done(c); } };
D.firfilter = { title: "FIR filter (tapped delay line)", cap: "y[n] = h0 x[n] + h1 x[n−1] + h2 x[n−2] + h3 x[n−3]. Each z⁻¹ box delays the signal by one sample. No feedback, so it is always stable.", draw() {
  const c = new Cv(400, 200, "FIR filter"); c.txt(4, 46, "x[n]", { c: "b" }); c.wire([[40, 42], [350, 42]], "in"); const hx = [70, 140, 210, 280]; [0, 1, 2, 3].forEach((i) => { const x = hx[i]; if (i) { c.box(x - 46, 30, 36, 24, "z⁻¹", "ff"); } c.wire([[x, 42], [x, 84]], "mid", true); c.dot(x, 42, "in"); c.add(mk("circle", { cx: x, cy: 98, r: 14, class: "dg-box on" })); c.txt(x, 103, "×", { a: "middle" }); c.txt(x + 18, 96, "h" + i, { c: "m" }); c.wire([[x, 112], [x, 150]], "out"); });
  c.wire([[70, 150], [300, 150]], "out"); c.add(mk("circle", { cx: 320, cy: 150, r: 14, class: "dg-box ff" })); c.txt(320, 155, "Σ", { a: "middle", c: "b" }); c.wire([[300, 150], [306, 150]], "out"); c.wire([[334, 150], [376, 150]], "out", true); c.txt(344, 142, "y[n]", { c: "g" }); return done(c); } };
D.iirfilter = { title: "IIR filter (first order, Direct Form II)", cap: "y[n] = b0 x[n] + b1 x[n\u22121] \u2212 a1 y[n\u22121]. The feedback (purple) gives a sharp response with few parts, but a pole can make it unstable.", draw() {
  const c = new Cv(400, 190, "IIR filter"); c.txt(4, 54, "x[n]", { c: "b" }); c.wire([[40, 50], [64, 50]], "in", true); c.add(mk("circle", { cx: 80, cy: 50, r: 14, class: "dg-box ff" })); c.txt(80, 55, "\u03A3", { a: "middle", c: "b" });
  c.wire([[94, 50], [236, 50]], "mid"); c.dot(150, 50, "mid"); c.txt(190, 42, "b0", { a: "middle", c: "m" }); c.add(mk("circle", { cx: 250, cy: 50, r: 14, class: "dg-box ff" })); c.txt(250, 55, "\u03A3", { a: "middle", c: "b" });
  c.wire([[150, 50], [150, 82]], "mid"); c.box(130, 82, 40, 26, "z\u207B\u00B9", "ff"); c.wire([[150, 108], [150, 140]], "mid"); c.dot(150, 140, "mid");
  c.wire([[150, 140], [80, 140], [80, 64]], "fb", true); c.txt(112, 134, "\u2212a1", { a: "middle", c: "m" }); c.wire([[150, 140], [250, 140], [250, 64]], "out", true); c.txt(205, 134, "b1", { a: "middle", c: "m" });
  c.wire([[264, 50], [340, 50]], "out", true); c.txt(344, 54, "y[n]", { c: "g" }); return done(c); } };
D.butterfly = { title: "4-point FFT (decimation in time)", cap: "The FFT splits the DFT into small butterflies. Each butterfly makes a sum and a difference. N points need (N/2) log₂N complex multiplications instead of N².", draw() {
  const c = new Cv(400, 230, "FFT butterfly"); const ys = [30, 80, 130, 180], names = ["x[0]", "x[2]", "x[1]", "x[3]"], outs = ["X[0]", "X[1]", "X[2]", "X[3]"]; names.forEach((n, i) => { c.txt(4, ys[i] + 4, n, { c: "b" }); c.wire([[44, ys[i]], [130, ys[i]]], "in"); });
  c.wire([[130, ys[0]], [200, ys[0]]], "mid"); c.wire([[130, ys[1]], [200, ys[1]]], "mid"); c.wire([[130, ys[2]], [200, ys[2]]], "mid"); c.wire([[130, ys[3]], [200, ys[3]]], "mid");
  c.wire([[130, ys[0]], [200, ys[1]]], "mid"); c.wire([[130, ys[1]], [200, ys[0]]], "clk"); c.wire([[130, ys[2]], [200, ys[3]]], "mid"); c.wire([[130, ys[3]], [200, ys[2]]], "clk"); [ys[0], ys[1], ys[2], ys[3]].forEach(y => { c.dot(130, y, "mid"); c.dot(200, y, "mid"); }); c.txt(166, 20, "stage 1", { a: "middle", c: "s" }); c.txt(166, 198, "(−1 on orange)", { a: "middle", c: "m" });
  c.wire([[200, ys[0]], [290, ys[0]]], "mid"); c.wire([[200, ys[1]], [290, ys[1]]], "mid"); c.wire([[200, ys[2]], [290, ys[2]]], "mid"); c.wire([[200, ys[3]], [290, ys[3]]], "mid"); c.wire([[200, ys[0]], [290, ys[2]]], "out"); c.wire([[200, ys[2]], [290, ys[0]]], "out"); c.wire([[200, ys[1]], [290, ys[3]]], "out"); c.wire([[200, ys[3]], [290, ys[1]]], "clk"); c.txt(246, 20, "stage 2 (twiddle W)", { a: "middle", c: "s" }); outs.forEach((n, i) => c.txt(298, ys[i] + 4, n, { c: "g" })); return done(c); } };
D.pzplot = { title: "Pole–zero plot (z-plane)", cap: "A discrete-time system is stable if all poles are inside the unit circle. Poles close to the circle give a sharp, lightly damped response.", draw() {
  const c = new Cv(340, 250, "Pole zero plot"); c.wire([[30, 125], [320, 125]], "ax", true); c.wire([[175, 240], [175, 10]], "ax", true); c.txt(318, 142, "Re(z)", { a: "end", c: "s" }); c.txt(182, 18, "Im(z)", { c: "s" }); c.add(mk("circle", { cx: 175, cy: 125, r: 90, class: "dg-ucircle" })); c.txt(240, 56, "unit circle", { c: "m" });
  c.fillp(Array.from({ length: 41 }, (_, i) => [175 + 90 * Math.cos(i * Math.PI / 20), 125 + 90 * Math.sin(i * Math.PI / 20)]), "g"); [[200, 90], [200, 160]].forEach(([x, y]) => { c.txt(x - 5, y + 5, "×", { c: "b" }); }); [[130, 125], [215, 125]].forEach(([x, y]) => { c.add(mk("circle", { cx: x, cy: y, r: 5, class: "dg-zero" })); }); c.txt(120, 112, "zero", { c: "s" }); c.txt(206, 84, "pole", { c: "b" }); c.txt(40, 238, "poles inside → stable", { c: "g" }); return done(c); } };
D.quant = { title: "Quantisation staircase", cap: "A quantiser rounds each sample to the nearest level. Step size Δ = range / 2ᴺ. Each extra bit adds about 6 dB of signal-to-noise ratio (SQNR ≈ 6.02N + 1.76 dB).", draw() {
  const c = new Cv(360, 250, "Quantiser"); c.axes(40, 20, 300, 180, "input", "output"); c.add(mk("line", { x1: 40, y1: 200, x2: 320, y2: 20, class: "dg-w in", "stroke-dasharray": "4 3" })); const st = []; for (let i = 0; i < 6; i++) { const x0 = 40 + i * 46, y = 200 - (i + 0.5) * 30; st.push([x0, y], [x0 + 46, y]); } c.curve(st, "out", 3); c.add(mk("line", { x1: 132, y1: 140, x2: 132, y2: 110, class: "dg-w clk" })); c.txt(138, 128, "Δ", { c: "m" }); c.txt(200, 238, "ideal (dashed) and quantised (green)", { a: "middle", c: "s" }); return done(c); } };
D.lpfresp = { title: "Low-pass filter response", cap: "Passband: signals pass. Stopband: signals are blocked. The transition band is where the response falls. Real filters have ripple and a transition band, not a perfect cliff.", draw() {
  const c = new Cv(360, 230, "Filter response"); c.axes(40, 20, 300, 170, "frequency", "|H|"); c.fillp([[40, 190], [40, 50], [150, 50], [150, 190]], "g"); c.fillp([[150, 190], [150, 50], [220, 50], [220, 190]], "p"); c.fillp([[220, 190], [220, 170], [340, 170], [340, 190]], "r"); c.curve([[40, 54], [80, 50], [110, 56], [140, 58], [160, 90], [190, 140], [220, 168], [260, 176], [300, 172], [340, 178]], "out", 3); c.txt(95, 40, "passband", { a: "middle", c: "g" }); c.txt(185, 40, "transition", { a: "middle", c: "m" }); c.txt(280, 160, "stopband", { a: "middle", c: "b" }); c.add(mk("line", { x1: 40, y1: 50, x2: 340, y2: 50, class: "dg-w ax", "stroke-dasharray": "2 4" })); c.txt(8, 54, "1", { c: "s" }); return done(c); } };
D.multirate = { title: "Decimation and interpolation", cap: "Decimation lowers the sampling rate by M (filter first to avoid aliasing). Interpolation raises it by L (insert zeros, then filter).", draw() {
  const c = new Cv(400, 190, "Multirate"); c.txt(4, 26, "Decimation", { c: "b" }); c.wire([[20, 64], [60, 64]], "in", true); c.box(60, 44, 90, 40, "Low-pass|filter", "ff"); c.wire([[150, 64], [190, 64]], "mid", true); c.box(190, 44, 70, 40, "↓ M", "on"); c.wire([[260, 64], [300, 64]], "out", true); c.txt(304, 68, "y[n]", { c: "g" });
  c.txt(4, 106, "Interpolation", { c: "b" }); c.wire([[20, 144], [60, 144]], "in", true); c.box(60, 124, 70, 40, "↑ L", "on"); c.wire([[130, 144], [190, 144]], "mid", true); c.box(190, 124, 90, 40, "Low-pass|filter", "ff"); c.wire([[280, 144], [320, 144]], "out", true); c.txt(324, 148, "y[n]", { c: "g" }); return done(c); } };

// ---- Control systems ----
D.blockrules = { title: "Block diagram reduction rules", cap: "Series: G1·G2. Parallel: G1 + G2. Negative feedback: G / (1 + GH). Reduce step by step until one block is left.", draw() {
  const c = new Cv(400, 250, "Block diagram rules"); const row = (y, lab, f) => { c.txt(4, y - 14, lab, { c: "b" }); f(y); };
  row(30, "Series", (y) => { c.wire([[20, y + 20], [50, y + 20]], "in", true); c.box(50, y + 4, 60, 32, "G1", "ff"); c.wire([[110, y + 20], [140, y + 20]], "mid", true); c.box(140, y + 4, 60, 32, "G2", "ff"); c.wire([[200, y + 20], [230, y + 20]], "out", true); c.txt(244, y + 24, "= G1·G2", { c: "m" }); });
  row(100, "Parallel", (y) => { c.wire([[20, y + 20], [40, y + 20], [40, y + 4], [60, y + 4]], "in", true); c.wire([[40, y + 20], [40, y + 36], [60, y + 36]], "in", true); c.box(60, y - 6, 56, 26, "G1", "ff"); c.box(60, y + 24, 56, 26, "G2", "ff"); c.wire([[116, y + 7], [150, y + 7], [150, y + 20]], "out"); c.wire([[116, y + 37], [150, y + 37], [150, y + 20]], "out"); c.add(mk("circle", { cx: 164, cy: y + 20, r: 12, class: "dg-box ff" })); c.txt(164, y + 25, "+", { a: "middle", c: "b" }); c.wire([[176, y + 20], [220, y + 20]], "out", true); c.txt(244, y + 24, "= G1 + G2", { c: "m" }); });
  row(180, "Feedback", (y) => { c.wire([[10, y + 14], [30, y + 14]], "in", true); c.add(mk("circle", { cx: 44, cy: y + 14, r: 12, class: "dg-box ff" })); c.txt(30, y + 4, "+", { c: "b" }); c.txt(48, y + 40, "−", { c: "m" }); c.wire([[56, y + 14], [80, y + 14]], "mid", true); c.box(80, y - 2, 56, 32, "G", "ff"); c.wire([[136, y + 14], [190, y + 14]], "out", true); c.dot(160, y + 14, "out"); c.wire([[160, y + 14], [160, y + 52], [136, y + 52]], "fb"); c.box(80, y + 38, 56, 28, "H", "ff"); c.wire([[80, y + 52], [44, y + 52], [44, y + 26]], "fb", true); c.txt(204, y + 18, "= G / (1 + GH)", { c: "m" }); }); return done(c); } };
D.stepresp2 = { title: "Second-order step response", cap: "Peak overshoot Mp = e^(−πζ/√(1−ζ²)), peak time tp = π/ωd, settling time ts ≈ 4/(ζωn) (2% band), rise time tr to reach the final value.", draw() {
  const c = new Cv(400, 250, "Step response"); c.axes(40, 20, 340, 190, "t", "c(t)"); const z = 0.4, wn = 1, wd = wn * Math.sqrt(1 - z * z), ph = Math.acos(z), f = (t) => 1 - Math.exp(-z * wn * t) * Math.sin(wd * t + ph) / Math.sqrt(1 - z * z), X = (t) => 40 + t * 22, Y = (v) => 210 - v * 100;
  c.add(mk("line", { x1: 40, y1: Y(1), x2: 380, y2: Y(1), class: "dg-w ax", "stroke-dasharray": "4 3" })); c.fillp([[40, Y(1.02)], [380, Y(1.02)], [380, Y(0.98)], [40, Y(0.98)]], "g"); c.curve(c.sample(200, (t) => [X(t), Y(f(t))], 0, 15), "out", 3);
  const tp = Math.PI / wd, mp = f(tp); c.add(mk("line", { x1: X(tp), y1: Y(mp), x2: X(tp), y2: 210, class: "dg-w clk", "stroke-dasharray": "3 3" })); c.dot(X(tp), Y(mp), "clk"); c.txt(X(tp) + 6, Y(mp) - 6, "Mp", { c: "m" }); c.txt(X(tp), 226, "tp", { a: "middle", c: "m" }); c.txt(X(4 / (z * wn)), 226, "ts", { a: "middle", c: "m" }); c.add(mk("line", { x1: X(4 / (z * wn)), y1: Y(1.02), x2: X(4 / (z * wn)), y2: 210, class: "dg-w clk", "stroke-dasharray": "3 3" })); c.txt(10, Y(1) + 4, "1", { c: "s" }); c.txt(330, Y(1) - 6, "final value", { a: "middle", c: "s" }); return done(c); } };
D.splane = { title: "s-plane and stability", cap: "A system is stable when every pole lies in the left half of the s-plane. A pole on the imaginary axis gives sustained oscillation; a pole in the right half grows without limit.", draw() {
  const c = new Cv(380, 240, "s-plane"); c.fillp([[190, 10], [190, 220], [30, 220], [30, 10]], "g"); c.fillp([[190, 10], [350, 10], [350, 220], [190, 220]], "r"); c.wire([[30, 115], [360, 115]], "ax", true); c.wire([[190, 226], [190, 6]], "ax", true); c.txt(356, 132, "σ", { a: "end", c: "s" }); c.txt(198, 16, "jω", { c: "s" });
  [[120, 85], [120, 145], [90, 115]].forEach(([x, y]) => c.txt(x - 5, y + 5, "×", { c: "b" })); [[270, 80], [270, 150]].forEach(([x, y]) => c.txt(x - 5, y + 5, "×", { c: "m" })); c.txt(60, 36, "Left half: stable", { c: "g" }); c.txt(210, 36, "Right half: unstable", { c: "m" }); c.txt(196, 130, "marginal", { c: "s" }); return done(c); } };
D.rootlocus = { title: "Root locus of K / [s(s + 2)]", cap: "The closed-loop poles move as the gain K grows. They start at the open-loop poles (0 and −2), meet at the breakaway point (−1), then go off along the vertical line Re(s) = −1.", draw() {
  const c = new Cv(380, 240, "Root locus"); c.wire([[20, 120], [360, 120]], "ax", true); c.wire([[190, 226], [190, 8]], "ax", true); c.txt(356, 138, "σ", { a: "end", c: "s" }); c.txt(198, 16, "jω", { c: "s" }); const X = (v) => 190 + v * 60;
  c.txt(X(0) - 5, 125, "×", { c: "b" }); c.txt(X(-2) - 5, 125, "×", { c: "b" }); c.curve([[X(-2), 120], [X(-1), 120]], "out", 3.4); c.curve([[X(-1), 120], [X(-1), 20]], "out", 3.4); c.curve([[X(-1), 120], [X(-1), 220]], "out", 3.4); c.dot(X(-1), 120, "clk"); c.txt(X(-1) + 6, 108, "breakaway", { c: "m" }); c.txt(X(-1) - 14, 136, "−1", { c: "s" }); c.txt(X(0) - 4, 138, "0", { c: "s" }); c.txt(X(-2) - 6, 138, "−2", { c: "s" }); c.add(mk("line", { x1: X(-1), y1: 22, x2: X(-1), y2: 40, class: "dg-w out" })); c.txt(X(-1) + 8, 44, "K → ∞", { c: "g" }); return done(c); } };
D.bodemag = { title: "Bode magnitude plot of 1 / (1 + s/ωc)", cap: "Flat at 0 dB up to the corner frequency ωc, then falls at −20 dB per decade (one pole). At ωc the true gain is −3 dB.", draw() {
  const c = new Cv(380, 240, "Bode plot"); c.axes(50, 20, 310, 180, "log ω", "dB"); c.add(mk("line", { x1: 50, y1: 70, x2: 360, y2: 70, class: "dg-w ax", "stroke-dasharray": "3 4" })); c.txt(8, 74, "0 dB", { c: "s" });
  c.curve([[50, 70], [180, 70], [340, 148]], "mid", 2); c.curve(c.sample(62, (t) => { const x = 50 + t * 5, w = Math.pow(10, (x - 180) / 66); return [x, 70 + 1.6 * 10 * Math.log10(1 + w * w)]; }, 0, 62), "out", 3);
  c.add(mk("line", { x1: 180, y1: 70, x2: 180, y2: 200, class: "dg-w clk", "stroke-dasharray": "3 3" })); c.txt(180, 216, "ωc", { a: "middle", c: "m" }); c.txt(258, 112, "−20 dB/decade", { c: "g" }); c.txt(100, 62, "flat", { c: "b" }); c.txt(184, 96, "−3 dB", { c: "m" }); return done(c); } };
D.pidblock = { title: "PID controller", cap: "u(t) = Kp e + Ki ∫ e dt + Kd de/dt. P reacts to the present error, I removes the steady-state error, D predicts and reduces overshoot.", draw() {
  const c = new Cv(420, 230, "PID controller"); c.txt(4, 114, "r", { c: "b" }); c.wire([[16, 110], [40, 110]], "in", true); c.add(mk("circle", { cx: 54, cy: 110, r: 12, class: "dg-box ff" })); c.txt(40, 100, "+", { c: "b" }); c.txt(58, 138, "−", { c: "m" }); c.wire([[66, 110], [96, 110]], "mid", true); c.txt(74, 102, "e", { c: "s" });
  c.dot(96, 110, "mid"); c.wire([[96, 110], [96, 40], [130, 40]], "mid"); c.wire([[96, 110], [130, 110]], "mid"); c.wire([[96, 110], [96, 180], [130, 180]], "mid"); c.box(130, 24, 80, 32, "P: Kp", "on"); c.box(130, 94, 80, 32, "I: Ki/s", "on"); c.box(130, 164, 80, 32, "D: Kd s", "on");
  c.wire([[210, 40], [240, 40], [240, 100]], "out"); c.wire([[210, 110], [228, 110]], "out"); c.wire([[210, 180], [240, 180], [240, 120]], "out"); c.add(mk("circle", { cx: 240, cy: 110, r: 12, class: "dg-box ff" })); c.txt(240, 115, "Σ", { a: "middle", c: "b" }); c.wire([[252, 110], [276, 110]], "out", true); c.box(276, 94, 64, 32, "Plant", "ff"); c.wire([[340, 110], [396, 110]], "out", true); c.txt(400, 114, "y", { c: "g" }); c.dot(366, 110, "out"); c.wire([[366, 110], [366, 215], [54, 215], [54, 122]], "fb", true); return done(c); } };
D.statespace = { title: "State-space model", cap: "ẋ = A x + B u and y = C x + D u. The poles of the system are the eigenvalues of A.", draw() {
  const c = new Cv(420, 210, "State space block diagram"); c.txt(4, 94, "u", { c: "b" }); c.wire([[16, 90], [50, 90]], "in", true); c.box(50, 74, 50, 32, "B", "ff"); c.wire([[100, 90], [136, 90]], "mid", true); c.add(mk("circle", { cx: 150, cy: 90, r: 12, class: "dg-box ff" })); c.txt(150, 95, "Σ", { a: "middle", c: "b" }); c.wire([[162, 90], [186, 90]], "mid", true); c.box(186, 74, 50, 32, "∫", "on"); c.txt(244, 82, "x", { c: "m" }); c.wire([[236, 90], [270, 90]], "mid"); c.dot(260, 90, "mid"); c.wire([[270, 90], [296, 90]], "mid", true); c.box(296, 74, 50, 32, "C", "ff"); c.add(mk("circle", { cx: 372, cy: 90, r: 12, class: "dg-box ff" })); c.txt(372, 95, "Σ", { a: "middle", c: "b" }); c.wire([[346, 90], [360, 90]], "mid", true); c.wire([[384, 90], [410, 90]], "out", true); c.txt(404, 82, "y", { c: "g" });
  c.wire([[260, 90], [260, 142], [150, 142], [150, 102]], "fb", true); c.box(190, 128, 50, 28, "A", "ff"); c.wire([[50, 190], [372, 190], [372, 102]], "clk", true); c.box(190, 176, 50, 26, "D", "ff"); c.wire([[20, 90], [20, 190], [50, 190]], "clk"); return done(c); } };
D.mason = { title: "Signal flow graph (Mason\u2019s gain formula)", cap: "T = (\u03A3 P\u2096 \u0394\u2096) / \u0394, with \u0394 = 1 \u2212 (sum of loop gains) + (sum of products of non-touching loop gains). Here one forward path G1G2G3 and two touching loops G2H1 and G3H2.", draw() {
  const c = new Cv(420, 210, "Signal flow graph"); const N = [[40, 110], [130, 110], [230, 110], [320, 110]]; N.forEach(([x, y], i) => { c.add(mk("circle", { cx: x, cy: y, r: 8, class: "dg-box ff" })); c.txt(x, y + 24, ["R", "x1", "x2", "C"][i], { a: "middle", c: "s" }); });
  [[0, 1, "G1"], [1, 2, "G2"], [2, 3, "G3"]].forEach(([a, b, t]) => { c.wire([[N[a][0] + 8, 110], [N[b][0] - 8, 110]], "out", true); c.txt((N[a][0] + N[b][0]) / 2, 100, t, { a: "middle", c: "m" }); });
  c.add(mk("path", { d: "M" + N[2][0] + " 102 Q" + ((N[1][0] + N[2][0]) / 2) + " 50 " + N[1][0] + " 102", class: "dg-w fb", fill: "none" })); c.txt((N[1][0] + N[2][0]) / 2, 62, "\u2212H1", { a: "middle", c: "m" });
  c.add(mk("path", { d: "M" + N[3][0] + " 118 Q" + ((N[2][0] + N[3][0]) / 2) + " 170 " + N[2][0] + " 118", class: "dg-w fb", fill: "none" })); c.txt((N[2][0] + N[3][0]) / 2, 168, "\u2212H2", { a: "middle", c: "m" });
  c.txt(210, 196, "T = G1G2G3 / (1 + G2H1 + G3H2)", { a: "middle", c: "s" }); return done(c); } };
D.nyquist = { title: "Nyquist plot", cap: "Plot G(jω)H(jω) for ω from 0 to ∞ (and its mirror image). Count how many times it encircles −1. Closed-loop stability: Z = P + N, and Z must be 0.", draw() {
  const c = new Cv(360, 240, "Nyquist plot"); c.wire([[20, 120], [340, 120]], "ax", true); c.wire([[180, 226], [180, 10]], "ax", true); c.txt(336, 138, "Re", { a: "end", c: "s" }); c.txt(188, 18, "Im", { c: "s" }); c.dot(140, 120, "clk"); c.txt(128, 140, "−1", { c: "m" });
  const pts = c.sample(60, (t) => { const w = 0.05 + t * 0.12, g = 2.2 / Math.sqrt(1 + w * w) / Math.sqrt(1 + (w / 3) ** 2) / Math.sqrt(1 + (w / 9) ** 2), ph = -Math.atan(w) - Math.atan(w / 3) - Math.atan(w / 9); return [180 + g * 40 * Math.cos(ph), 120 + g * 40 * Math.sin(ph)]; }, 0, 60); c.curve(pts, "out", 3); c.curve(pts.map(p => [p[0], 240 - p[1]]), "mid", 2.2); c.txt(222, 80, "ω increasing", { c: "g" }); c.txt(222, 212, "mirror (−ω)", { c: "b" }); c.txt(20, 36, "no encirclement of −1", { c: "g" }); c.txt(20, 52, "→ stable (P = 0)", { c: "g" }); return done(c); } };

// ---- Probability and random variables ----
const gauss = (x, m, sd) => Math.exp(-0.5 * ((x - m) / sd) ** 2) / (sd * Math.sqrt(2 * Math.PI));
D.bell = { title: "Normal (Gaussian) distribution", cap: "About 68% of values lie within 1σ of the mean, 95% within 2σ and 99.7% within 3σ. Standardise with Z = (X − μ) / σ.", draw() {
  const c = new Cv(380, 240, "Normal distribution"); const X = (z) => 190 + z * 52, Y = (z) => 200 - gauss(z, 0, 1) * 440;
  const band = (a, b, cls) => c.fillp([[X(a), 200]].concat(c.sample(40, (t) => [X(t), Y(t)], a, b)).concat([[X(b), 200]]), cls);
  band(-3, 3, "b"); band(-2, 2, "g"); band(-1, 1, "p"); c.curve(c.sample(80, (t) => [X(t), Y(t)], -3.4, 3.4), "in", 3); c.wire([[16, 200], [364, 200]], "ax", true);
  [-3, -2, -1, 0, 1, 2, 3].forEach(z => { c.add(mk("line", { x1: X(z), y1: 200, x2: X(z), y2: 206, class: "dg-w ax" })); c.txt(X(z), 220, z === 0 ? "μ" : (z > 0 ? "+" : "−") + Math.abs(z) + "σ", { a: "middle", c: "s" }); });
  c.txt(190, 130, "68%", { a: "middle", c: "b" }); c.txt(100, 168, "95%", { a: "middle", c: "g" }); c.txt(56, 188, "99.7%", { a: "middle", c: "m" }); return done(c); } };
D.pdfcdf = { title: "PDF and CDF", cap: "The PDF f(x) is the density: the area under it gives probability. The CDF F(x) = P(X ≤ x) is the running area. It rises from 0 to 1 and never decreases. f(x) = dF/dx.", draw() {
  const c = new Cv(400, 230, "PDF and CDF"); c.txt(4, 20, "PDF f(x)", { c: "b" }); c.txt(214, 20, "CDF F(x)", { c: "g" }); c.wire([[10, 150], [190, 150]], "ax", true); c.wire([[10, 150], [10, 30]], "ax", true); c.wire([[214, 150], [394, 150]], "ax", true); c.wire([[214, 150], [214, 30]], "ax", true);
  const X = (z) => 100 + z * 28, Y = (z) => 150 - gauss(z, 0, 1) * 220; c.fillp([[X(-3), 150]].concat(c.sample(30, (t) => [X(t), Y(t)], -3, 0.6)).concat([[X(0.6), 150]]), "b"); c.curve(c.sample(60, (t) => [X(t), Y(t)], -3, 3), "in", 3); c.add(mk("line", { x1: X(0.6), y1: 150, x2: X(0.6), y2: Y(0.6), class: "dg-w clk", "stroke-dasharray": "3 3" })); c.txt(X(0.6), 168, "a", { a: "middle", c: "m" }); c.txt(60, 128, "P(X ≤ a) = shaded area", { c: "s" });
  const cd = (z) => 0.5 * (1 + (z < 0 ? -1 : 1) * Math.sqrt(1 - Math.exp(-2 * z * z / Math.PI))), X2 = (z) => 304 + z * 28, Y2 = (v) => 150 - v * 110; c.curve(c.sample(60, (t) => [X2(t), Y2(cd(t))], -3, 3), "out", 3); c.add(mk("line", { x1: 214, y1: Y2(1), x2: 394, y2: Y2(1), class: "dg-w ax", "stroke-dasharray": "3 4" })); c.txt(398, Y2(1) + 4, "1", { a: "end", c: "s" }); c.dot(X2(0.6), Y2(cd(0.6)), "clk"); c.add(mk("line", { x1: X2(0.6), y1: Y2(cd(0.6)), x2: X2(0.6), y2: 150, class: "dg-w clk", "stroke-dasharray": "3 3" })); c.txt(X2(0.6), 168, "a", { a: "middle", c: "m" }); c.txt(260, 200, "F(a) = P(X ≤ a)", { c: "s" }); return done(c); } };
D.venn = { title: "Venn diagram: union and intersection", cap: "P(A ∪ B) = P(A) + P(B) − P(A ∩ B). The overlap is counted twice by P(A) + P(B), so it is subtracted once.", draw() {
  const c = new Cv(380, 220, "Venn diagram"); c.add(mk("rect", { x: 20, y: 14, width: 340, height: 160, rx: 10, class: "dg-box off" })); c.txt(32, 34, "S (sample space)", { c: "s" }); c.add(mk("circle", { cx: 150, cy: 100, r: 62, class: "dg-venn a" })); c.add(mk("circle", { cx: 230, cy: 100, r: 62, class: "dg-venn b" })); c.txt(110, 104, "A", { a: "middle", c: "b" }); c.txt(272, 104, "B", { a: "middle", c: "g" }); c.txt(190, 98, "A ∩ B", { a: "middle", c: "m" }); c.txt(190, 196, "P(A ∪ B) = P(A) + P(B) − P(A ∩ B)", { a: "middle", c: "s" }); return done(c); } };
D.bayestree = { title: "Probability tree and Bayes’ theorem", cap: "P(D | +) = P(+ | D) P(D) / P(+). With P(D) = 1%, sensitivity 95% and false-positive rate 5%, a positive test means only about a 16% chance of the disease.", draw() {
  const c = new Cv(460, 250, "Probability tree"); c.dot(30, 120, "in"); c.txt(20, 140, "start", { c: "s" }); c.wire([[30, 120], [120, 60]], "in"); c.wire([[30, 120], [120, 190]], "mid"); c.txt(48, 82, "D: 0.01", { c: "b" }); c.txt(40, 174, "no D: 0.99", { c: "m" });
  c.wire([[120, 60], [250, 30]], "in"); c.wire([[120, 60], [250, 90]], "mid"); c.wire([[120, 190], [250, 160]], "in"); c.wire([[120, 190], [250, 220]], "mid"); c.txt(160, 34, "+ 0.95", { c: "b" }); c.txt(160, 94, "− 0.05", { c: "s" }); c.txt(160, 164, "+ 0.05", { c: "b" }); c.txt(160, 224, "− 0.95", { c: "s" });
  c.txt(256, 34, "D and +  = 0.0095", { c: "g" }); c.txt(256, 94, "D and −  = 0.0005", { c: "s" }); c.txt(256, 164, "no D and +  = 0.0495", { c: "m" }); c.txt(256, 224, "no D and −  = 0.9405", { c: "s" }); return done(c); } };
D.binomial = { title: "Binomial distribution, n = 6, p = 0.5", cap: "P(X = k) = C(n,k) pᵏ (1−p)ⁿ⁻ᵏ. Mean np = 3, variance np(1−p) = 1.5. Heights are 1, 6, 15, 20, 15, 6, 1 out of 64.", draw() {
  const c = new Cv(380, 230, "Binomial distribution"), v = [1, 6, 15, 20, 15, 6, 1]; c.wire([[24, 190], [360, 190]], "ax", true); v.forEach((h, k) => { const x = 40 + k * 46, y = 190 - h * 7.4; c.add(mk("rect", { x, y, width: 34, height: 190 - y, rx: 4, class: "dg-box on" })); c.txt(x + 17, 208, String(k), { a: "middle", c: "s" }); c.txt(x + 17, y - 5, h + "/64", { a: "middle", c: "g" }); }); c.txt(190, 226, "number of successes k", { a: "middle", c: "s" }); return done(c); } };
D.dists3 = { title: "Uniform, exponential and Gaussian", cap: "Uniform: all values equally likely (mean (a+b)/2, variance (b−a)²/12). Exponential: waiting time, f(x) = λe^(−λx), mean 1/λ. Gaussian: the bell curve.", draw() {
  const c = new Cv(420, 190, "Three distributions"); [[10, "Uniform"], [150, "Exponential"], [290, "Gaussian"]].forEach(([x, t]) => { c.txt(x + 60, 20, t, { a: "middle", c: "b" }); c.wire([[x, 150], [x + 120, 150]], "ax", true); c.wire([[x, 150], [x, 34]], "ax"); });
  c.fillp([[40, 150], [40, 80], [100, 80], [100, 150]], "b"); c.curve([[40, 80], [100, 80]], "in", 3); c.txt(70, 70, "1/(b−a)", { a: "middle", c: "s" }); c.txt(40, 166, "a", { a: "middle", c: "s" }); c.txt(100, 166, "b", { a: "middle", c: "s" });
  c.curve(c.sample(40, (t) => [150 + t * 2.6, 150 - 100 * Math.exp(-t / 14)], 0, 44), "out", 3); c.fillp([[150, 150]].concat(c.sample(40, (t) => [150 + t * 2.6, 150 - 100 * Math.exp(-t / 14)], 0, 44)).concat([[264, 150]]), "g"); c.txt(160, 44, "λ", { c: "g" });
  c.curve(c.sample(60, (t) => [350 + t * 16, 150 - gauss(t, 0, 1) * 260], -3.4, 3.4), "mid", 3); c.fillp([[296, 150]].concat(c.sample(40, (t) => [350 + t * 16, 150 - gauss(t, 0, 1) * 260], -3.4, 3.4)).concat([[404, 150]]), "p"); c.txt(350, 166, "μ", { a: "middle", c: "s" }); return done(c); } };
D.acf = { title: "Autocorrelation and power spectral density", cap: "R(τ) and the PSD form a Fourier-transform pair (Wiener–Khinchin). White noise: R(τ) is a spike at 0 and the PSD is flat. Low-pass noise: R(τ) is wider and the PSD is narrow.", draw() {
  const c = new Cv(420, 250, "Autocorrelation and PSD"); const panel = (x, y, lab, f, cls) => { c.txt(x, y - 12, lab, { c: "b" }); c.wire([[x, y + 60], [x + 150, y + 60]], "ax", true); c.wire([[x + 75, y + 70], [x + 75, y]], "ax"); c.curve(c.sample(60, (t) => [x + 75 + t * 70, y + 60 - f(t) * 52], -1, 1), cls, 3); };
  c.txt(4, 12, "White noise", { c: "m" }); c.add(mk("line", { x1: 100, y1: 74, x2: 100, y2: 22, class: "dg-w in", "stroke-width": 4 })); c.wire([[20, 74], [190, 74]], "ax", true); c.txt(100, 90, "R(τ)  spike at τ = 0", { a: "middle", c: "s" }); c.wire([[230, 74], [400, 74]], "ax", true); c.curve([[236, 48], [394, 48]], "out", 3); c.txt(318, 90, "PSD flat (all frequencies)", { a: "middle", c: "s" });
  c.txt(4, 132, "Low-pass noise", { c: "m" }); c.wire([[20, 214], [190, 214]], "ax", true); c.curve(c.sample(60, (t) => [105 + t * 80, 214 - 76 * Math.exp(-3 * Math.abs(t))], -1, 1), "in", 3); c.txt(100, 232, "R(τ) decays slowly", { a: "middle", c: "s" }); c.wire([[230, 214], [400, 214]], "ax", true); c.curve(c.sample(60, (t) => [315 + t * 80, 214 - 76 / (1 + 22 * t * t)], -1, 1), "out", 3); c.txt(318, 232, "PSD concentrated at low f", { a: "middle", c: "s" }); return done(c); } };

D.designflow = { title: "The digital design process", cap: "Specify, design, simulate, build a prototype and test. If a step fails, loop back and fix it.", draw() {
  const c = new Cv(450, 470, "Digital design process flowchart"); const diamond = (x, y, w, h, label, cls) => { c.add(mk("polygon", { points: [x + w / 2, y, x + w, y + h / 2, x + w / 2, y + h, x, y + h / 2].join(" "), class: "dg-box " + (cls || "on") })); c.txt(x + w / 2, y + h / 2 + 4, label, { a: "middle", c: "b" }); };
  c.box(20, 6, 150, 34, "Required product", "on"); c.wire([[95, 40], [95, 56]], "in", true); c.box(20, 56, 150, 34, "Define specifications", "ff"); c.wire([[95, 90], [95, 106]], "in", true); c.box(20, 106, 150, 34, "Initial design", "ff"); c.wire([[95, 140], [95, 156]], "in", true); c.box(20, 156, 150, 34, "Simulation (CAD)", "ff");
  c.wire([[95, 190], [95, 206]], "in", true); diamond(25, 206, 140, 56, "Design correct?"); c.wire([[165, 234], [230, 234], [230, 190]], "fb"); c.txt(180, 228, "No", { c: "m" }); c.box(200, 156, 130, 34, "Redesign", "off"); c.wire([[230, 173], [165, 173]], "fb", true);
  c.wire([[95, 262], [95, 292]], "out", true); c.txt(104, 282, "Yes", { c: "g" }); c.box(20, 292, 150, 34, "Prototype", "ff"); c.wire([[95, 326], [95, 342]], "in", true); c.box(20, 342, 150, 34, "Testing", "ff"); c.wire([[95, 376], [95, 392]], "in", true); diamond(25, 392, 140, 56, "Meets specs?");
  c.wire([[95, 448], [95, 462]], "out", true); c.txt(104, 460, "Yes", { c: "g" }); c.txt(100, 468, "", {}); c.box(200, 392, 130, 34, "Minor errors?", "off"); c.wire([[165, 420], [200, 410]], "fb", true); c.txt(172, 432, "No", { c: "m" }); c.box(200, 342, 130, 34, "Make corrections", "ff"); c.wire([[265, 392], [265, 376]], "out", true); c.txt(272, 386, "Yes", { c: "g" }); c.wire([[200, 359], [165, 359]], "out", true); c.wire([[330, 409], [360, 409], [360, 173], [330, 173]], "fb", true); c.txt(362, 300, "No: big errors,", { c: "m" }); c.txt(362, 314, "redesign", { c: "m" });
  c.txt(246, 462, "Finished product", { a: "middle", c: "g" }); return done(c); } };

D.layers = { title: "From a computer down to a transistor", cap: "A computer is built in layers. Each layer is made of many parts of the layer below it.", draw() {
  const c = new Cv(400, 300, "Layers of digital hardware"); const L = [["Computer", "case, power supply, disks", "ff"], ["Motherboard (PCB)", "a board that carries many chips", "on"], ["Chip (IC)", "billions of transistors on silicon", "ff"], ["Logic gates", "AND, OR, NOT, flip-flops", "on"], ["Transistor", "a tiny electronic switch", "ff"]];
  L.forEach(([t, s, k], i) => { const y = 8 + i * 58, x = 20 + i * 14, w = 360 - i * 28; c.box(x, y, w, 44, t + "|" + s, k); if (i < 4) c.wire([[200, y + 44], [200, y + 58]], "in", true); }); c.txt(386, 150, "contains", { a: "end", c: "s" }); return done(c); } };
D.chiptypes = { title: "Three ways to build a logic circuit", cap: "A rough comparison. Standard chips are simple and fixed. An FPGA is programmed by you. An ASIC is made at a factory for one job.", draw() {
  const c = new Cv(400, 300, "Chip types"); const cols = [["Standard chips", "fixed function", [1, 2, 1], "ff"], ["FPGA (PLD)", "you program it", [5, 3, 2], "on"], ["ASIC (custom)", "made in a factory", [1, 5, 5], "off"]], rows = ["Can change later", "Speed and size", "Start-up cost"], colr = ["#7c3aed", "#16a34a", "#ea580c"];
  cols.forEach(([t, s, v, k], i) => { const x = 10 + i * 128; c.box(x, 10, 118, 48, t + "|" + s, k); v.forEach((n, r) => { const y = 82 + r * 66; c.txt(x + 4, y, rows[r], { c: "s" }); for (let j = 0; j < 5; j++) c.add(mk("rect", { x: x + 4 + j * 22, y: y + 8, width: 18, height: 18, rx: 4, fill: j < n ? colr[r] : "#e2e8f0", "fill-opacity": j < n ? ".85" : "1" })); }); });
  c.txt(200, 290, "more filled boxes = more of it", { a: "middle", c: "s" }); return done(c); } };
D.moore = { title: "Moore’s law: more transistors every year", cap: "The number of transistors on a chip roughly doubles about every two years. That is why chips got from thousands of transistors to billions.", draw() {
  const c = new Cv(400, 250, "Moore law"); c.axes(60, 20, 320, 190, "year", "transistors"); const Y = (e) => 210 - (e - 3) * 22; [[3, "10³"], [6, "10⁶"], [9, "10⁹"], [11, "10¹¹"]].forEach(([e, t]) => { c.add(mk("line", { x1: 56, y1: Y(e), x2: 380, y2: Y(e), class: "dg-w ax", "stroke-dasharray": "2 5", "stroke-width": 1 })); c.txt(52, Y(e) + 4, t, { a: "end", c: "s" }); });
  c.curve([[70, Y(3.4)], [370, Y(10.7)]], "out", 3.4); [[110, "1970s: thousands"], [210, "1990s: millions"], [316, "2010s+: billions"]].forEach(([x, t]) => { const e = 3.4 + (x - 70) / 300 * 7.3; c.dot(x, Y(e), "clk"); c.txt(x - 4, Y(e) - 10, t, { a: "middle", c: "m" }); }); c.txt(220, 238, "straight line on a log scale = doubling again and again", { a: "middle", c: "s" }); return done(c); } };
D.dec2bin = { title: "Decimal to binary: divide by 2", cap: "Keep dividing by 2 and write each remainder. Read the remainders from the bottom up: 25 = 11001 in binary.", draw() {
  const c = new Cv(400, 290, "Decimal to binary"); const rows = [[25, 12, 1], [12, 6, 0], [6, 3, 0], [3, 1, 1], [1, 0, 1]]; c.txt(20, 20, "Number ÷ 2", { c: "s" }); c.txt(170, 20, "Quotient", { c: "s" }); c.txt(290, 20, "Remainder", { c: "s" });
  rows.forEach(([n, q, r], i) => { const y = 30 + i * 42; c.box(10, y, 120, 32, n + " ÷ 2", "ff"); c.box(150, y, 90, 32, "= " + q, "ff"); c.box(270, y, 90, 32, String(r), r ? "on" : "off"); });
  c.wire([[376, 190], [376, 40]], "clk", true); c.txt(366, 238, "read upward", { a: "end", c: "m" }); c.txt(200, 262, "Answer: 1 1 0 0 1  =  11001₂", { a: "middle", c: "g" }); return done(c); } };
D.dacpath = { title: "Digital to analog: how a music player works", cap: "Music is stored as binary numbers (digital). A D/A converter turns them into a changing voltage (analog) that moves the speaker.", draw() {
  const c = new Cv(400, 230, "Digital to analog"); c.box(10, 40, 100, 60, "Memory", "ff"); c.txt(60, 128, "1100100110", { a: "middle", c: "g" }); c.txt(60, 146, "1001000100 …", { a: "middle", c: "g" }); c.txt(60, 164, "digital", { a: "middle", c: "m" });
  c.wire([[110, 70], [150, 70]], "mid", true); c.box(150, 40, 100, 60, "D/A", "on"); c.wire([[250, 70], [290, 70]], "out", true); c.box(290, 40, 100, 60, "Speaker", "ff");
  c.curve([[160, 190], [190, 170], [220, 205], [250, 175], [280, 200], [310, 180], [340, 195]], "out", 2.5); c.txt(250, 224, "analog: a smoothly changing voltage", { a: "middle", c: "m" }); return done(c); } };
D.bitsrange = { title: "How many bits do I need?", cap: "n bits can show 2ⁿ different values, from 0 up to 2ⁿ − 1. Pick the smallest n whose range reaches your number.", draw() {
  const c = new Cv(400, 250, "Bits and range"); c.txt(20, 20, "bits n", { c: "s" }); c.txt(110, 20, "values 2ⁿ", { c: "s" }); c.txt(230, 20, "largest number", { c: "s" });
  [[4, 16, 15], [8, 256, 255], [10, 1024, 1023], [16, 65536, 65535]].forEach(([n, v, m], i) => { const y = 30 + i * 46; c.box(10, y, 70, 34, String(n), "ff"); c.box(100, y, 100, 34, String(v), "ff"); c.box(220, y, 120, 34, String(m), "on"); });
  c.txt(200, 232, "270 needs 9 bits because 256 ≤ 270 < 512", { a: "middle", c: "g" }); return done(c); } };
D.switches = { title: "Switches make AND and OR", cap: "Switches in series work like AND: the light is on only if both are closed. Switches in parallel work like OR: the light is on if either is closed.", draw() {
  const c = new Cv(400, 250, "Series and parallel switches");
  c.txt(10, 16, "Series = AND   L = x₁ · x₂", { c: "b" }); c.wire([[20, 50], [60, 50]], "in"); c.box(60, 34, 56, 32, "S x₁", "ff"); c.wire([[116, 50], [150, 50]], "mid"); c.box(150, 34, 56, 32, "S x₂", "ff"); c.wire([[206, 50], [250, 50]], "mid"); c.box(250, 34, 66, 32, "Light L", "on"); c.dot(20, 50, "in");
  c.txt(10, 112, "Parallel = OR   L = x₁ + x₂", { c: "m" }); c.wire([[20, 160], [60, 160], [60, 130], [100, 130]], "in"); c.wire([[60, 160], [60, 200], [100, 200]], "in"); c.box(100, 114, 56, 32, "S x₁", "ff"); c.box(100, 184, 56, 32, "S x₂", "ff");
  c.wire([[156, 130], [190, 130], [190, 160]], "mid"); c.wire([[156, 200], [190, 200], [190, 160]], "mid"); c.wire([[190, 160], [250, 160]], "mid"); c.box(250, 144, 66, 32, "Light L", "on"); c.dot(60, 160, "in"); c.dot(190, 160, "mid");
  c.txt(336, 54, "both closed", { c: "s" }); c.txt(336, 164, "any closed", { c: "s" }); return done(c); } };
D.bvenn = { title: "Venn diagrams for AND, OR and NOT", cap: "Shaded area means the expression is 1. x·y is the overlap, x + y is both circles together, and x′ is everything outside the circle x.", draw() {
  const c = new Cv(400, 190, "Boolean Venn diagrams");
  const panel = (ox, title, kind) => { const cy = 75, R = 28, ax = ox + 44, bx = ox + 74, mx = ox + 59;
    c.add(mk("rect", { x: ox, y: 20, width: 118, height: 110, rx: 6, class: kind === "n" ? "dg-grp g1" : "dg-cell", "fill-opacity": kind === "n" ? 0.25 : 1, "stroke-width": 1.5 }));
    if (kind === "n") { c.add(mk("circle", { cx: mx, cy, r: 30, fill: "#fff", class: "dg-box off" })); c.txt(mx, cy + 4, "x", { a: "middle", c: "s" }); }
    else { [ax, bx].forEach(q => c.add(mk("circle", { cx: q, cy, r: R, class: kind === "o" ? "dg-grp g2" : "dg-box off", "fill-opacity": kind === "o" ? 0.35 : 0.5 })));
      if (kind === "a") c.add(mk("path", { d: "M" + mx + " " + (cy - 23.6) + "A28 28 0 0 1 " + mx + " " + (cy + 23.6) + "A28 28 0 0 1 " + mx + " " + (cy - 23.6) + "Z", class: "dg-grp g1", "fill-opacity": 0.7 }));
      c.txt(ax - 14, cy + 4, "x", { a: "middle", c: "s" }); c.txt(bx + 14, cy + 4, "y", { a: "middle", c: "s" }); }
    c.txt(mx, 152, title, { a: "middle", c: kind === "o" ? "g" : kind === "a" ? "b" : "m" }); };
  panel(8, "x · y  (AND)", "a"); panel(140, "x + y  (OR)", "o"); panel(272, "x′  (NOT)", "n");
  c.txt(200, 180, "shaded area = the places where the answer is 1", { a: "middle", c: "s" }); return done(c); } };
D.kmap3pi = { title: "Prime implicants on a 3-variable map", cap: "f = Σm(0,1,2,3,7). The blue group of 4 gives x₁′. The green group of 2 gives x₂x₃. Both are essential, so f = x₁′ + x₂x₃.", draw() {
  const c = new Cv(330, 190, "3-variable Karnaugh map"), x0 = 70, y0 = 40, cw = 56, ch = 46, cols = [0, 1, 3, 2], ones = new Set([0, 1, 2, 3, 7]);
  c.txt(x0 + 2 * cw, 16, "x₁x₂", { a: "middle", c: "b" }); c.txt(24, y0 + ch + 4, "x₃", { c: "b" });
  for (let r = 0; r < 2; r++) for (let k = 0; k < 4; k++) { const m = (cols[k] << 1) | r, x = x0 + k * cw, y = y0 + r * ch; c.add(mk("rect", { x, y, width: cw, height: ch, class: "dg-cell" })); c.txt(x + cw / 2, y + ch / 2 + 6, ones.has(m) ? "1" : "0", { a: "middle", c: ones.has(m) ? "one" : "zero" }); c.txt(x + cw - 4, y + 11, String(m), { a: "end", c: "mn" }); }
  c.add(mk("rect", { x: x0 + 3, y: y0 + 3, width: 2 * cw - 6, height: 2 * ch - 6, rx: 12, class: "dg-grp g1" })); c.add(mk("rect", { x: x0 + cw + 8, y: y0 + ch + 8, width: 2 * cw - 16, height: ch - 16, rx: 10, class: "dg-grp g2" }));
  ["00", "01", "11", "10"].forEach((l, i) => c.txt(x0 + i * cw + cw / 2, y0 - 6, l, { a: "middle", c: "m" })); ["0", "1"].forEach((l, i) => c.txt(x0 - 8, y0 + i * ch + ch / 2 + 4, l, { a: "end", c: "m" }));
  c.txt(x0 + cw, y0 + 2 * ch + 22, "x₁′", { a: "middle", c: "b" }); c.txt(x0 + 2 * cw, y0 + 2 * ch + 22, "x₂x₃", { a: "middle", c: "g" }); return done(c); } };
D.nandnand = { title: "AND–OR becomes NAND–NAND", cap: "f = x₂ + x₁x₃′. Replace every gate by a NAND (tie the inputs of a NAND together to make a NOT) and the same circuit works with only NAND gates.", draw() {
  const c = new Cv(340, 300, "NAND only circuit"); c.txt(8, 14, "AND–OR form", { c: "b" }); c.txt(8, 154, "NAND–NAND form", { c: "g" });
  [["x₁", 50], ["x₃", 98], ["x₂", 118], ["x₁", 190], ["x₃", 236], ["x₂", 274]].forEach(([t, y]) => c.txt(4, y + 4, t, { c: "b" }));
  c.wire([[26, 98], [40, 98]], "in"); const n = c.gate("not", 40, 78); const a = c.gate("and", 120, 40); c.wire([[26, 50], [120, 50]], "in");
  c.wire([n.o, [100, n.o[1]], [100, 70], [120, 70]], "mid"); const o = c.gate("or", 200, 70); c.wire([a.o, [180, a.o[1]], [180, 80], [204, 80]], "mid"); c.wire([[26, 118], [204, 118], [204, 100]], "in"); c.wire([o.o, [300, o.o[1]]], "out", true); c.txt(304, o.o[1] + 4, "f", { c: "g" });
  const tie = (y, bx) => { c.wire([[26, y], [bx, y]], "in"); c.wire([[bx, y - 10], [bx, y + 10]], "in"); c.wire([[bx, y - 10], [bx + 6, y - 10]], "in"); c.wire([[bx, y + 10], [bx + 6, y + 10]], "in"); c.dot(bx, y, "in"); };
  tie(236, 34); const nb = c.gate("nand", 40, 216); const nc = c.gate("nand", 120, 180); c.wire([[26, 194], [26, 190], [120, 190]], "in"); c.wire([nb.o, [105, nb.o[1]], [105, 210], [120, 210]], "mid");
  tie(274, 110); const n2 = c.gate("nand", 120, 254); const fin = c.gate("nand", 210, 222); c.wire([nc.o, [190, nc.o[1]], [190, 232], [210, 232]], "mid"); c.wire([n2.o, [190, n2.o[1]], [190, 252], [210, 252]], "mid"); c.wire([fin.o, [320, fin.o[1]]], "out", true); c.txt(322, fin.o[1] + 4, "f", { c: "g" }); return done(c); } };
D.cadflow = { title: "From idea to chip: the CAD flow", cap: "Design entry (a schematic or Verilog) goes through synthesis, simulation, physical design and timing checks before the chip is built or programmed.", draw() {
  const c = new Cv(400, 330, "CAD design flow"), st = [["1  Design entry", "schematic or Verilog", "ff"], ["2  Synthesis", "turns the design into gates", "ff"], ["3  Functional simulation", "does it work? (no delays)", "on"], ["4  Physical design", "place and wire on the chip", "ff"], ["5  Timing simulation", "is it fast enough?", "on"], ["6  Chip configuration", "program the FPGA / make the chip", "ff"]];
  st.forEach(([t, d, k], i) => { const y = 8 + i * 52; c.box(20, y, 260, 38, t + "|" + d, k); if (i < st.length - 1) c.wire([[150, y + 38], [150, y + 52]], "mid", true); });
  c.wire([[280, 118], [320, 118], [320, 27], [280, 27]], "fb", true); c.txt(326, 70, "wrong?", { c: "m" }); c.txt(326, 84, "fix it", { c: "m" }); return done(c); } };
D.sevenseg = { title: "Seven-segment display", cap: "Seven LED bars a to g make the digits. For the numbers 0, 1 and 2 only some bars are lit. Each bar is a logic function of the inputs.", draw() {
  const c = new Cv(400, 190, "Seven segment display"), seg = (x, y, lit) => { const S = { a: [8, 0, 28, 7], b: [36, 8, 7, 28], c: [36, 44, 7, 28], d: [8, 72, 28, 7], e: [0, 44, 7, 28], f: [0, 8, 7, 28], g: [8, 36, 28, 7] }; Object.keys(S).forEach(k => { const [dx, dy, w, h] = S[k]; c.add(mk("rect", { x: x + dx, y: y + dy, width: w, height: h, rx: 3, class: "dg-box " + (lit.includes(k) ? "on" : "off") })); c.txt(x + dx + w / 2, y + dy + h / 2 + 4, k, { a: "middle", c: "s" }); }); };
  seg(20, 20, "abcdef"); seg(150, 20, "bc"); seg(280, 20, "abdeg"); c.txt(41, 128, "0", { a: "middle", c: "b" }); c.txt(171, 128, "1", { a: "middle", c: "b" }); c.txt(301, 128, "2", { a: "middle", c: "b" });
  c.txt(200, 160, "for s₁s₀ = 00, 01, 10:  a = d = e = s₀′,  b = 1,  c = s₁′", { a: "middle", c: "g" }); return done(c); } };
D.func16 = { title: "All 16 functions of two variables", cap: "Two inputs x, y have 4 rows, so there are 2⁴ = 16 possible functions. Eight of them are the standard gates: AND, OR, NAND, NOR, XOR, XNOR, NOT and the buffer.", draw() {
  const c = new Cv(400, 204, "16 functions"), x0 = 38, cw = 22, y0 = 34, ch = 26, nm = { 1: "AND", 6: "XOR", 7: "OR", 8: "NOR", 9: "XNOR", 14: "NAND" };
  c.txt(4, 24, "xy", { c: "s" }); for (let k = 0; k < 16; k++) { const x = x0 + k * cw; c.txt(x + cw / 2, 24, "F" + k, { a: "middle", c: nm[k] ? "m" : "s" });
    for (let r = 0; r < 4; r++) { const v = (k >> (3 - r)) & 1; c.add(mk("rect", { x, y: y0 + r * ch, width: cw - 1, height: ch - 1, class: "dg-cell" + (nm[k] ? " hi" : "") })); c.txt(x + cw / 2, y0 + r * ch + 17, String(v), { a: "middle", c: v ? "one" : "zero" }); }
    if (nm[k]) c.txt(x + cw / 2, y0 + 4 * ch + 14 + (k === 9 ? 11 : 0), nm[k], { a: "middle", c: "mn" }); }
  ["00", "01", "10", "11"].forEach((l, r) => c.txt(x0 - 6, y0 + r * ch + 17, l, { a: "end", c: "m" })); c.txt(200, 192, "F0 = constant 0,  F15 = constant 1,  F3 = x,  F5 = y,  F10 = y′,  F12 = x′", { a: "middle", c: "s" }); return done(c); } };
D.polarity = { title: "Positive and negative logic", cap: "The same voltage signal can mean 1 or 0. Positive logic: high voltage H is 1. Negative logic: low voltage L is 1. So one physical NAND gate is a NOR gate in negative logic.", draw() {
  const c = new Cv(400, 210, "Positive and negative logic"), panel = (ox, t, hv, lv, cls) => { c.txt(ox + 80, 18, t, { a: "middle", c: cls }); c.wire([[ox + 30, 40], [ox + 160, 40]], "fb"); c.wire([[ox + 30, 110], [ox + 160, 110]], "fb");
    c.txt(ox + 22, 44, "H", { a: "end", c: "s" }); c.txt(ox + 22, 114, "L", { a: "end", c: "s" }); c.wire([[ox + 40, 110], [ox + 85, 110], [ox + 85, 40], [ox + 150, 40]], cls === "b" ? "in" : "out");
    c.box(ox + 36, 124, 44, 26, "H = " + hv, "ff"); c.box(ox + 88, 124, 44, 26, "L = " + lv, "off"); };
  panel(8, "Positive logic", "1", "0", "b"); panel(208, "Negative logic", "0", "1", "g");
  c.box(40, 162, 320, 36, "7400 gate:  positive logic → NAND|negative logic → NOR", "on"); return done(c); } };
D.famtable = { title: "Typical logic-family numbers", cap: "Typical values from the textbook table (older chips). CMOS uses almost no power but was slower; ECL is the fastest; TTL is in between. Newer CMOS families are much faster today.", draw() {
  const c = new Cv(400, 210, "Logic family table"), cols = [[8, 96, "Family"], [108, 56, "Fan-out"], [168, 66, "Power mW"], [238, 70, "Delay ns"], [312, 80, "Noise V"]],
    rows = [["Standard TTL", 10, 10, 10, 0.4], ["Schottky TTL", 10, 22, 3, 0.4], ["LP Schottky", 20, 2, 10, 0.4], ["ECL", 25, 25, 2, 0.2], ["CMOS", 50, 0.1, 25, 3]];
  cols.forEach(([x, w, t]) => c.box(x, 6, w, 26, t, "ff")); rows.forEach((r, i) => cols.forEach(([x, w], j) => { const best = (j === 2 && r[0] === "CMOS") || (j === 3 && r[0] === "ECL") || (j === 1 && r[0] === "CMOS") || (j === 4 && r[0] === "CMOS"); c.box(x, 38 + i * 32, w, 28, String(r[j]), best ? "on" : "off"); })); c.txt(200, 206, "green = best in that column", { a: "middle", c: "g" }); return done(c); } };
export function drawDiagram2(key) { const d = D[key]; if (!d) return null; try { return { title: d.title, cap: d.cap, svg: d.draw() }; } catch (_) { return null; } }
